-- Baseline 1: complete SQLite application schema at version 15. Immutable after release.

CREATE TABLE public."teams" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ux_teams_name" ON public."teams" ("name");

CREATE TABLE public."segments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ux_segments_name" ON public."segments" ("name");

CREATE TABLE public."blocks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ux_blocks_name" ON public."blocks" ("name");

CREATE TABLE public."users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "last_name" TEXT COLLATE "C",
    "first_name" TEXT COLLATE "C" NOT NULL,
    "middle_name" TEXT COLLATE "C",
    "password_hash" TEXT COLLATE "C",
    "role" TEXT COLLATE "C" NOT NULL DEFAULT 'user',
    "login" TEXT COLLATE "C",
    "is_assignee" INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idx_users_login" ON public."users" ("login");

CREATE TABLE public."block_templates" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT COLLATE "C" NOT NULL,
    "segment_id" BIGINT NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("segment_id") REFERENCES public."segments" ("id") ON DELETE NO ACTION
);

CREATE UNIQUE INDEX "ux_block_templates_name" ON public."block_templates" ("name");

CREATE TABLE public."team_blocks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "team_id" BIGINT NOT NULL,
    "block_name" TEXT COLLATE "C" NOT NULL,
    "schedule_offset" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("team_id") REFERENCES public."teams" ("id") ON DELETE CASCADE
);

CREATE INDEX "idx_team_blocks_team_id" ON public."team_blocks" ("team_id");

CREATE TABLE public."user_team_access" (
    "user_id" BIGINT NOT NULL,
    "team_id" BIGINT NOT NULL,
    PRIMARY KEY ("user_id", "team_id"),
    FOREIGN KEY ("team_id") REFERENCES public."teams" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("user_id") REFERENCES public."users" ("id") ON DELETE CASCADE
);

CREATE INDEX "idx_user_team_access_team_id" ON public."user_team_access" ("team_id");

CREATE TABLE public."freeze_days" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "date" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ux_freeze_days_date" ON public."freeze_days" ("date");

CREATE TABLE public."template_blocks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "template_id" BIGINT NOT NULL,
    "block_id" BIGINT NOT NULL,
    "schedule_offset" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("block_id") REFERENCES public."blocks" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("template_id") REFERENCES public."block_templates" ("id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "ux_template_blocks_template_id_block_id" ON public."template_blocks" ("template_id", "block_id");

CREATE TABLE public."team_templates" (
    "team_id" BIGINT NOT NULL,
    "template_id" BIGINT NOT NULL,
    PRIMARY KEY ("team_id", "template_id"),
    FOREIGN KEY ("template_id") REFERENCES public."block_templates" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("team_id") REFERENCES public."teams" ("id") ON DELETE CASCADE
);

CREATE TABLE public."tasks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "team_id" BIGINT NOT NULL,
    "segment_id" BIGINT NOT NULL,
    "name" TEXT COLLATE "C" NOT NULL,
    "description" TEXT COLLATE "C",
    "instruction_url" TEXT COLLATE "C",
    "criticality" TEXT COLLATE "C" NOT NULL DEFAULT 'medium',
    "priority" BIGINT NOT NULL DEFAULT 0,
    "task_status" TEXT COLLATE "C" NOT NULL DEFAULT 'new',
    "psi_status" TEXT COLLATE "C" NOT NULL DEFAULT 'not_required',
    "completed_at" TEXT COLLATE "C",
    "completion_template_id" BIGINT,
    "is_deleted" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("team_id") REFERENCES public."teams" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("completion_template_id") REFERENCES public."block_templates" ("id") ON DELETE SET NULL,
    FOREIGN KEY ("segment_id") REFERENCES public."segments" ("id") ON DELETE NO ACTION
);

CREATE INDEX "idx_tasks_team_completed_at" ON public."tasks" ("team_id", "completed_at");

CREATE INDEX "idx_tasks_team_id" ON public."tasks" ("team_id");

CREATE TABLE public."assignments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "task_id" BIGINT NOT NULL,
    "date" TEXT COLLATE "C" NOT NULL,
    "block" TEXT COLLATE "C",
    "status" TEXT COLLATE "C" NOT NULL DEFAULT 'new',
    "user_id" BIGINT,
    "comment" TEXT COLLATE "C",
    "is_psi" INTEGER NOT NULL DEFAULT 0,
    "time_spent" TEXT COLLATE "C",
    "is_deleted" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("user_id") REFERENCES public."users" ("id") ON DELETE NO ACTION,
    FOREIGN KEY ("task_id") REFERENCES public."tasks" ("id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "ux_assignments_task_date" ON public."assignments" ("task_id", "date") WHERE is_deleted = 0;

CREATE INDEX "idx_assignments_status" ON public."assignments" ("status");

CREATE INDEX "idx_assignments_date" ON public."assignments" ("date");

CREATE INDEX "idx_assignments_task_id" ON public."assignments" ("task_id");

CREATE TABLE public."task_dependencies" (
    "task_id" BIGINT NOT NULL,
    "depends_on_task_id" BIGINT NOT NULL,
    PRIMARY KEY ("task_id", "depends_on_task_id"),
    FOREIGN KEY ("depends_on_task_id") REFERENCES public."tasks" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("task_id") REFERENCES public."tasks" ("id") ON DELETE CASCADE
);

CREATE TABLE public."task_history" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "task_id" BIGINT NOT NULL,
    "action" TEXT COLLATE "C" NOT NULL,
    "field_name" TEXT COLLATE "C",
    "old_value" TEXT COLLATE "C",
    "new_value" TEXT COLLATE "C",
    "event_id" TEXT COLLATE "C",
    "changed_at" TEXT COLLATE "C" NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    "changed_by_user_id" BIGINT,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("changed_by_user_id") REFERENCES public."users" ("id") ON DELETE SET NULL,
    FOREIGN KEY ("task_id") REFERENCES public."tasks" ("id") ON DELETE CASCADE
);

CREATE INDEX "idx_task_history_event_id" ON public."task_history" ("event_id");

CREATE INDEX "idx_task_history_create_cursor" ON public."task_history" ("action", "changed_at", "id", "task_id");

CREATE INDEX "idx_task_history_task_id" ON public."task_history" ("task_id");

CREATE TABLE public."assignment_history" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "assignment_id" BIGINT NOT NULL,
    "task_id" BIGINT NOT NULL,
    "date" TEXT COLLATE "C" NOT NULL,
    "action" TEXT COLLATE "C" NOT NULL,
    "field_name" TEXT COLLATE "C",
    "old_value" TEXT COLLATE "C",
    "new_value" TEXT COLLATE "C",
    "event_id" TEXT COLLATE "C",
    "changed_at" TEXT COLLATE "C" NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    "changed_by_user_id" BIGINT,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("changed_by_user_id") REFERENCES public."users" ("id") ON DELETE SET NULL,
    FOREIGN KEY ("task_id") REFERENCES public."tasks" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("assignment_id") REFERENCES public."assignments" ("id") ON DELETE CASCADE
);

CREATE INDEX "idx_assignment_history_event_id" ON public."assignment_history" ("event_id");

CREATE INDEX "idx_assignment_history_task_id" ON public."assignment_history" ("task_id");

CREATE INDEX "idx_assignment_history_assignment_id" ON public."assignment_history" ("assignment_id");

CREATE TABLE public."user_new_task_notification_state" (
    "user_id" BIGINT,
    "new_tasks_seen_at" TEXT COLLATE "C" NOT NULL,
    "new_tasks_seen_history_id" BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY ("user_id"),
    FOREIGN KEY ("user_id") REFERENCES public."users" ("id") ON DELETE CASCADE
);

CREATE TABLE public."user_new_task_notification_seen_events" (
    "user_id" BIGINT NOT NULL,
    "task_history_id" BIGINT NOT NULL,
    "seen_at" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("user_id", "task_history_id"),
    FOREIGN KEY ("task_history_id") REFERENCES public."task_history" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("user_id") REFERENCES public."users" ("id") ON DELETE CASCADE
);

CREATE INDEX "idx_user_new_task_notification_seen_events_seen_at" ON public."user_new_task_notification_seen_events" ("seen_at");

CREATE INDEX "idx_user_new_task_notification_seen_events_history" ON public."user_new_task_notification_seen_events" ("task_history_id");

CREATE TABLE public."application_metadata" (
    "id" BIGINT CHECK (id = 1),
    "release_version" TEXT COLLATE "C" NOT NULL,
    "build_id" TEXT COLLATE "C" NOT NULL,
    "updated_at" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE public."user_release_change_log_seen" (
    "user_id" BIGINT NOT NULL,
    "release_version" TEXT COLLATE "C" NOT NULL,
    "seen_at" TEXT COLLATE "C" NOT NULL,
    PRIMARY KEY ("user_id", "release_version"),
    FOREIGN KEY ("user_id") REFERENCES public."users" ("id") ON DELETE CASCADE
);
